  var sModalCombinarOpo=useState(null); var modalCombinarOpo=sModalCombinarOpo[0]; var setModalCombinarOpo=sModalCombinarOpo[1];
  // confirmPedidoOportunidadP: null, o {clienteId,resumen} , la pregunta
